// Draw fish
function drawFish(x, y, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x - 20, y - 10);
    ctx.lineTo(x - 30, y);
    ctx.lineTo(x - 20, y + 10);
    ctx.lineTo(x, y);
    ctx.fill();

    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.moveTo(x - 15, y - 5);
    ctx.lineTo(x - 25, y);
    ctx.lineTo(x - 15, y + 5);
    ctx.fill();
}

