];

// Draw circles with gradient fill
for (let i = 0; i < 6; i++) {
  const radius = maxRadius - i * 20;
  const gradient = ctx.createRadialGradient(
    centerX, centerY,
    radius - 20,
    centerX, centerY,
    radius + 10
  );

  const startColor = colors[i % 6];
  const endColor = colors[(i + 1) % 6];

  gradient.addColorStop(0, startColor);
  gradient.addColorStop(1, endColor);

  ctx.beginPath();
  ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
  ctx.fillStyle = gradient;
  ctx.fill();

  // Add a subtle border to each circle
  ctx.strokeStyle = '#2d2d57';
  ctx.lineWidth = 2;
  ctx.stroke();
}

