// Draw jellyfish body
const cx = W/2;
const cy = H/2 + 50;
const radius = 40;

// Main body
ctx.fillStyle = '#ffccaa';
ctx.beginPath();
ctx.arc(cx, cy, radius, 0, Math.PI * 2);
ctx.fill();

// Tentacles
ctx.fillStyle = '#ffbb99';
for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI * 2;
    const x1 = cx + Math.cos(angle) * radius;
    const y1 = cy + Math.sin(angle) * radius;

    // Tentacle
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(
        x1 + Math.cos(angle) * (radius + 20),
        y1 + Math.sin(angle) * (radius + 20)
    );

    // Tentacle tip
    ctx.lineTo(
        x1 + Math.cos(angle) * (radius + 30),
        y1 + Math.sin(angle) * (radius + 30)
    );

    ctx.closePath();
    ctx.fill();

    // Tentacle pulsation effect
    ctx.strokeStyle = '#ff9966';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(
        x1 + Math.cos(angle) * (radius + 20 + Math.sin(i * 0.5)),
        y1 + Math.sin(angle) * (radius + 20 + Math.sin(i * 0.5))
    );
    ctx.stroke();
}

