ctx.lineWidth = 1;
for (let i = 0; i < 10; i++) {
    const angle = (i * Math.PI) / 5;
    const radius = 50 + i * 15;
    const x = 200 + Math.cos(angle) * radius;
    const y = 250 - Math.sin(angle) * radius;
    if (i === 0) {
        ctx.beginPath();
        ctx.moveTo(x, y);
    } else {
        ctx.lineTo(x, y);
    }
}
ctx.stroke();

